import Alpine from 'alpinejs';
import { getLogger } from '~/lib/log';

const log = getLogger('Store: Layout');

// Global layout store for cross-component communication
Alpine.store('layout', {
  promoBarHeight: 0,
  headerHeight: 0,
  headerStyle: 'solid',

  setPromoBarHeight(height) {
    this.promoBarHeight = height;
    log.debug('Promo bar height updated', { height });
  },

  getPromoBarHeight() {
    return this.promoBarHeight;
  },

  setHeaderHeight(height) {
    this.headerHeight = height;
    log.debug('Header height updated', { height });
  },

  getHeaderHeight() {
    return this.headerHeight;
  },

  setHeaderStyle(style) {
    this.headerStyle = style;
    log.debug('Header style updated', { style });
  },

  getHeaderStyle() {
    return this.headerStyle;
  },
});
